    int ret;

    pr_info("tala: Device plugged in.\n");

    device = interface_to_usbdev(interface);
    bulk_buf = kzalloc(PACKET_SIZE, GFP_KERNEL);
    if (!bulk_buf) {
        pr_err("tala_probe: Failed to allocate memory for bulk buffer.\n");
        return -ENOMEM;
    }

