    if (ret) {
        pr_err("tala_probe: Failed to register device (error %d).\n", ret);
        kfree(bulk_buf);
        bulk_buf = NULL;
    } else {
        pr_info("tala: Device registered successfully (minor %d).\n", interface->minor);
    }

    return ret;
}

