    usb_deregister_dev(interface, &tala_class);

    if (bulk_buf) {
        memset(bulk_buf, 0, PACKET_SIZE); /* Clear sensitive data */
        kfree(bulk_buf);
        bulk_buf = NULL;
    }

    pr_info("tala: Device disconnected.\n");
}

