	// Add numbers to the linked list
	for _, numStr := range numsStr {
		num, err := strconv.ParseUint(numStr, 10, 32)
		if err != nil {
			log.Fatalf("Error parsing number: %s", err)
		}
		list.AddTail(uint32(num))
	}

	// Process the list for 10 iterations
