	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	return lines, scanner.Err()
}

func remoteRun(user string, addr string, pass string, cmd string, wg *sync.WaitGroup) (string, error) {
	defer wg.Done()

	config := &ssh.ClientConfig{
		User:            user,
		HostKeyCallback: ssh.InsecureIgnoreHostKey(),
		Auth: []ssh.AuthMethod{
			ssh.Password(pass),
		},
		Timeout: 40 * time.Second,
	}

	client, err := ssh.Dial("tcp", net.JoinHostPort(addr, port), config)
	if err != nil {
		return "", err
	}
	defer client.Close()

	session, err := client.NewSession()
	if err != nil {
		return "", err
	}
	defer session.Close()

	var b bytes.Buffer
	session.Stdout = &b

	err = session.Run(cmd)
	if err != nil {
		return "", err
	}

	if isExcludedSystem(b.String()) {
		log.Printf("IP %s excluded due to system: %s", addr, b.String())
		return "", nil
	}

	return b.String(), nil
}

// Worker function that runs SSH commands in a controlled manner.
func worker(id int, jobs <-chan string, wg *sync.WaitGroup) {
	defer wg.Done()

	for ip := range jobs {
		output, err := remoteRun("root", ip, "password", "uname -a", wg)
		if err == nil {
			fmt.Printf("Worker %d: Success for IP %s: %s\n", id, ip, output)
		} else {
			fmt.Printf("Worker %d: Error for IP %s: %s\n", id, ip, err)
		}
	}
}

func main() {
	lines, err := readLines(ipfile)
	if err != nil {
		log.Fatalf("readLines: %s", err)
	}

	var wg sync.WaitGroup
	uniqueIPs := make(map[string]bool)

	for _, line := range lines {
		ip := strings.TrimSpace(line)
		if ip != "" {
			uniqueIPs[ip] = true
		}
	}

	var ips []string
	for ip := range uniqueIPs {
		ips = append(ips, ip)
	}

	// Create a channel to pass jobs (IP addresses) to workers
	jobs := make(chan string, len(ips))

	// Launch workers
	numWorkers := 5 // Define the number of concurrent workers
	for w := 1; w <= numWorkers; w++ {
		wg.Add(1)
		go worker(w, jobs, &wg)
	}

	// Send the IPs to the workers
	for _, ip := range ips {
		jobs <- ip
	}
	close(jobs)

	// Wait for all workers to complete
	wg.Wait()

	timeout := 90 * time.Second
	if waitTimeout(&wg, timeout) {
		fmt.Println("Execution timed out")
	} else {
		fmt.Println("Execution completed")
	}
}

package main

import (
	"fmt"
	"io"
	"log"
	"os"
	"strconv"
	"strings"
)

type Info struct {
	start, end int
}

func main() {
	// Open the file
	f, err := os.Open("tinput.txt")
	if err != nil {
		log.Fatalf("Error opening file: %s", err)
	}
	defer f.Close()

	// Read the entire file into memory
	bytes, err := io.ReadAll(f)
	if err != nil {
		log.Fatalf("Error reading file: %s", err)
	}
	input := string(bytes)

	// Split the input by spaces to get the numbers
	numsStr := strings.Split(input, " ")

	// Create a new linked list
	list := &LinkedList{}
	fmt.Println("Initial Input:", numsStr)

	// Add numbers to the linked list
	for _, numStr := range numsStr {
		num, err := strconv.ParseUint(numStr, 10, 32)
		if err != nil {
			log.Fatalf("Error parsing number: %s", err)
		}
		list.AddTail(uint32(num))
	}

	// Process the list for 10 iterations
	for i := 0; i < 10; i++ {
		current := list.head
		for current != nil {
			if current.value == 0 {
				current.value = 1
			} else if current.HasEvenDigits() {
				list.Replace(current)
			} else {
				current.value *= 2024
			}
			current = current.next
		}
		list.PrintLinkedList()
	}
}

// Node represents an element in the linked list
type Node struct {
	value    uint32
	previous *Node
	next     *Node
}

// HasEvenDigits checks if the node's value has an even number of digits
func (n *Node) HasEvenDigits() bool {
	str := fmt.Sprintf("%d", n.value)
	return len(str)%2 == 0
}

// Replace splits the node's value into two new nodes
func (n *Node) Replace() (*Node, *Node) {
	numStr := fmt.Sprintf("%d", n.value)
	mid := len(numStr) / 2
	num1, _ := strconv.ParseInt(numStr[:mid], 10, 64)
	num2, _ := strconv.ParseInt(numStr[mid:], 10, 64)

	// Create new nodes for the split value
	newNode1 := &Node{value: uint32(num1), previous: n.previous}
	if n.previous != nil {
		n.previous.next = newNode1
	}

	newNode2 := &Node{value: uint32(num2), next: n.next}
	if n.next != nil {
		n.next.previous = newNode2
	}

	// Link the new nodes together
	newNode1.next = newNode2
	newNode2.previous = newNode1
	return newNode1, newNode2
}

// LinkedList represents a doubly linked list
type LinkedList struct {
	head   *Node
	tail   *Node
	length int
}

// Replace handles replacing a node in the list
func (ll *LinkedList) Replace(current *Node) {
	node, node2 := current.Replace()
	if ll.head == current {
		ll.head = node
	} else if ll.tail == current {
		ll.tail = node2
	}
	ll.length++
}

// AddTail adds a new node with a given value to the end of the list
func (ll *LinkedList) AddTail(value uint32) {
	node := &Node{value: value}
	if ll.tail == nil {
		ll.head = node
		ll.tail = node
	} else {
		ll.tail.next = node
		node.previous = ll.tail
		ll.tail = node
	}
	ll.length++
}

// PrintLinkedList prints all the values in the linked list
func (ll LinkedList) PrintLinkedList() {
	current := ll.head
	for current != nil {
		fmt.Printf("%d ", current.value)
		current = current.next
	}
	fmt.Println()
}

